"""`.Body overlay positioning`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Body overlay positioning'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Overlay 1', 'NodeSocketVector', min_value=0.0, max_value=0.0)
    t.socket('OUTPUT', 'Overlay 2', 'NodeSocketVector', min_value=0.0, max_value=0.0)

    t.node('NodeFrame', 'Frame.001', props={
        'location': (74.0, 164.0),
        'width': 246.65741,
        'height': 277.0,
        'label': 'Overlay 2 positioning',
    })
    t.node('NodeFrame', 'Frame', props={
        'location': (-198.0, 167.0),
        'width': 250.54561,
        'height': 277.0,
        'label': 'Overlay 1 positioning',
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (382.1636, 111.8007),
    })
    t.node('ShaderNodeGroup', 'Group.001', parent='Frame.001', inputs={'Scale X': 15.0, 'Scale Y': 15.0, 'Position X': 9.4, 'Position Y': 45.0}, props={
        'node_tree': lib.group('Scale Vector'),
        'location': (29.777931, -40.326645),
        'width': 186.65742,
    })
    t.node('ShaderNodeGroup', 'Group', parent='Frame', inputs={'Scale X': 15.0, 'Scale Y': 15.0, 'Position X': 5.9, 'Position Y': 45.0}, props={
        'node_tree': lib.group('Scale Vector'),
        'location': (30.227707, -39.799103),
        'width': 190.54561,
    })
    t.node('ShaderNodeUVMap', 'bodyuv', props={
        'location': (-461.92194, 52.4718),
        'width': 150.0,
    })

    t.link('Group', 'Coordinates', 'Group Output', 'Overlay 1')
    t.link('Group.001', 'Coordinates', 'Group Output', 'Overlay 2')
    t.link('bodyuv', 'UV', 'Group', 'UV Map')
    t.link('bodyuv', 'UV', 'Group.001', 'UV Map')
    return t
